-- 3-yangilanish: filial boshlig'i, selfi, qurilma, oylik hisob, xarajat, taklif, SOS, hujjatlar. SQL Editor'da bir marta ishga tushiring.
alter table profiles drop constraint if exists profiles_role_check;
alter table profiles add constraint profiles_role_check check(role in('admin','manager','employee','driver'));
alter table profiles add column if not exists leave_days int default 15,add column if not exists device_id text;
alter table attendance add column if not exists photo text,add column if not exists acc float8;
alter table trips add column if not exists sign_photo text,add column if not exists region boolean default false;
grant update(status,collected,arrived_at,arrive_photo,arrive_note,sign_photo) on trips to authenticated;
create table pay_params(user_id uuid primary key references profiles on delete cascade,base_salary numeric default 0,plan numeric default 0,pct_ok numeric default 0,pct_low numeric default 0,rate_city numeric default 0,rate_region numeric default 0,hour_rate numeric default 0);
create table pay_inputs(user_id uuid references profiles on delete cascade,month text,sales numeric default 0,primary key(user_id,month));
create table settings(key text primary key,value text);
create table payslips(user_id uuid references profiles on delete cascade,month text,data jsonb,created_at timestamptz default now(),primary key(user_id,month));
create table expenses(id bigserial primary key,user_id uuid references profiles,amount numeric,note text,photo text,status text default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz default now());
create table feedback(id bigserial primary key,user_id uuid references profiles,body text,created_at timestamptz default now());
create table sos(id bigserial primary key,user_id uuid references profiles,lat float8,lng float8,created_at timestamptz default now());
create table documents(id bigserial primary key,user_id uuid references profiles,title text,path text,created_at timestamptz default now());
create function is_mgr_of(uid uuid) returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from profiles m join profiles u on u.branch_id=m.branch_id where m.id=auth.uid() and m.role='manager' and u.id=uid)$$;
drop function if exists mark(text,float8,float8,text);
create function mark(k text,la float8,ln float8,tok text,ph text default null,ac float8 default null) returns text language plpgsql security definer set search_path=public as $$
declare p profiles;b branches;d float8;l attendance;
begin
select * into p from profiles where id=auth.uid();
select * into b from branches where qr_token=tok;
if b.id is null then raise exception 'QR kod noto''g''ri'; end if;
if p.branch_id is not null and p.branch_id<>b.id and p.role<>'driver' then raise exception 'Bu boshqa filialning QR kodi'; end if;
d:=12742000*asin(sqrt(power(sin(radians(la-b.lat)/2),2)+cos(radians(b.lat))*cos(radians(la))*power(sin(radians(ln-b.lng)/2),2)));
if d>b.radius then raise exception 'Filial hududidan % m uzoqdasiz',round(d); end if;
select * into l from attendance where user_id=p.id and created_at>=date_trunc('day',now() at time zone 'Asia/Tashkent') at time zone 'Asia/Tashkent' order by created_at desc limit 1;
if k='in' and l.kind='in' then raise exception 'Siz allaqachon "Keldim" bosgansiz'; end if;
if k='out' and (l.id is null or l.kind='out') then raise exception 'Avval "Keldim" bosing'; end if;
insert into attendance(user_id,branch_id,kind,lat,lng,photo,acc) values(p.id,b.id,k,la,ln,ph,ac);
return 'ok';end$$;
create function touch_device(d text) returns text language plpgsql security definer set search_path=public as $$
declare cur text;begin select device_id into cur from profiles where id=auth.uid();
if cur is null then update profiles set device_id=d where id=auth.uid();return 'ok';end if;
if cur=d then return 'ok';end if;
insert into audit(actor,action,detail) values(auth.uid(),'Boshqa qurilmadan kirdi','');return 'diff';end$$;
alter table pay_params enable row level security;alter table pay_inputs enable row level security;alter table settings enable row level security;alter table payslips enable row level security;
alter table expenses enable row level security;alter table feedback enable row level security;alter table sos enable row level security;alter table documents enable row level security;
create policy y1 on pay_params for all to authenticated using(is_admin()) with check(is_admin());
create policy y2 on pay_inputs for all to authenticated using(is_admin()) with check(is_admin());
create policy y3 on settings for all to authenticated using(is_admin()) with check(is_admin());
create policy y4 on payslips for select to authenticated using(user_id=auth.uid() or is_admin());
create policy y5 on payslips for all to authenticated using(is_admin()) with check(is_admin());
create policy e1 on expenses for select to authenticated using(user_id=auth.uid() or is_admin());
create policy e2 on expenses for insert to authenticated with check(user_id=auth.uid() and status='pending');
create policy e3 on expenses for update to authenticated using(is_admin()) with check(is_admin());
create policy f1 on feedback for insert to authenticated with check(user_id is null or user_id=auth.uid());
create policy f2 on feedback for select to authenticated using(is_admin());
create policy s1 on sos for insert to authenticated with check(user_id=auth.uid());
create policy s2 on sos for select to authenticated using(is_admin() or is_mgr_of(user_id));
create policy d1 on documents for select to authenticated using(user_id=auth.uid() or is_admin());
create policy d2 on documents for all to authenticated using(is_admin()) with check(is_admin());
create policy a3 on attendance for select to authenticated using(is_mgr_of(user_id));
create policy l4 on leaves for select to authenticated using(is_mgr_of(user_id));
create policy l5 on leaves for update to authenticated using(is_mgr_of(user_id)) with check(is_mgr_of(user_id));
create policy k5 on tasks for select to authenticated using(is_mgr_of(user_id));
create policy k6 on tasks for insert to authenticated with check(is_mgr_of(user_id));
create policy k7 on tasks for delete to authenticated using(is_mgr_of(user_id));
create policy n3 on announcements for insert to authenticated with check(branch_id is not null and exists(select 1 from profiles where id=auth.uid() and role='manager' and branch_id=announcements.branch_id));
insert into storage.buckets(id,name,public) values('docs','docs',false) on conflict do nothing;
create policy dc1 on storage.objects for insert to authenticated with check(bucket_id='docs' and is_admin());
create policy dc2 on storage.objects for select to authenticated using(bucket_id='docs' and (is_admin() or (storage.foldername(name))[1]=auth.uid()::text));
drop policy if exists ph2 on storage.objects;
create policy ph3 on storage.objects for select to authenticated using(bucket_id='photos' and ((storage.foldername(name))[1]=auth.uid()::text or is_admin() or is_mgr_of(((storage.foldername(name))[1])::uuid)));
